/**
 * The trivia bank, in English: built from src/lib/trivia.ts, so it cannot drift.
 * Keys: trivia.<n>.q (the question) and trivia.<n>.o0 … o3 (the options, in the
 * bank's order, so the bank's correctIndex is right in every language).
 * The other languages' files are generated by scripts/lang-content/build.mjs.
 */
import { TRIVIA_BANK } from '../../../lib/trivia';

const messages: Record<string, string> = {};
TRIVIA_BANK.forEach((q, n) => {
  messages[`trivia.${n}.q`] = q.question;
  q.options.forEach((o, i) => {
    messages[`trivia.${n}.o${i}`] = o;
  });
});

export default messages;
